import {
  AUTH_REQUIRED_MESSAGE,
  errorResult,
  okResult,
  type CliCommandResult,
} from '../envelope';
import { booleanFlag, integerFlag, stringFlag } from '../flags';
import { isCommandResult, parseCommandContext } from './shared';

const COMMAND = 'evidence.capture';

const EVIDENCE_FLAG_SPEC = {
  url: { takesValue: true },
  screenshot: { takesValue: false },
  width: { takesValue: true },
  height: { takesValue: true },
};

export const handleEvidenceCapture = async (
  args: string[],
): Promise<CliCommandResult> => {
  const context = parseCommandContext(COMMAND, args, EVIDENCE_FLAG_SPEC);
  if (isCommandResult(context)) {
    return context;
  }
  const url = stringFlag(context.flags, 'url');
  if (!url?.trim()) {
    return errorResult(
      COMMAND,
      'USAGE_ERROR',
      'Usage: rivet evidence capture --url <url> [--screenshot] [--width N --height N]',
    );
  }
  const width = integerFlag(context.flags, 'width');
  const height = integerFlag(context.flags, 'height');
  if (context.flags.errors.length > 0) {
    return errorResult(COMMAND, 'USAGE_ERROR', context.flags.errors.join('; '));
  }

  const { getConfigManager } = await import('../../services/ConfigManager');
  if (!getConfigManager().isAuthenticated()) {
    return errorResult(
      COMMAND,
      'AUTH_REQUIRED',
      AUTH_REQUIRED_MESSAGE,
    );
  }

  const { BrowserAgentClient } =
    await import('../../services/BrowserAgentClient');
  const client = new BrowserAgentClient();
  const result = await client.captureDesignEvidence(url, {
    screenshot: booleanFlag(context.flags, 'screenshot'),
    ...(width && height ? { viewport: { width, height } } : {}),
  });
  if (!result.ok) {
    return errorResult(COMMAND, 'OPERATION_FAILED', result.reason, {
      available: result.available,
    });
  }
  return okResult(COMMAND, { evidence: result.evidence });
};
